"use client";

import { useTexture } from "@react-three/drei";
import { useMemo } from "react";
import * as THREE from "three";
import type { PackFormat } from "@/content/types";

/**
 * Concept packs built from simple geometry (no paid models).
 * Every pack's front face is the 5:7 label texture generated by `npm run labels`.
 * Units: a pack front is 1 wide × 1.4 tall.
 */
export interface PackModelProps {
  format: PackFormat;
  front: string;
  back: string;
  /** Side panel texture (cartons, sacks, pouches, sleeves). */
  side: string;
  colour: string;
}

const LW = 1;
const LH = 1.4;

function useLabel(front: string, back: string, side: string) {
  const [f, b, s] = useTexture([front, back, side]);
  for (const t of [f, b, s]) {
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 4;
  }
  return [f, b, s] as const;
}

/** Pillow-shaped box: thickness tapers to the seams. Used for sacks and pouches. */
function pillowGeometry(depth: number, profile: (ny: number) => number, edge = 6) {
  const g = new THREE.BoxGeometry(LW, LH, depth, 28, 36, 4);
  const pos = g.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const nx = x / (LW / 2), ny = y / (LH / 2);
    const pinch = Math.sqrt(Math.max(0, 1 - Math.abs(nx) ** edge)) * profile(ny);
    pos.setZ(i, z * Math.max(pinch, 0.04));
    // slight barrel bulge on the faces
    pos.setX(i, x * (1 + 0.035 * (1 - ny * ny) * Math.abs(z / (depth / 2))));
  }
  g.computeVertexNormals();
  return g;
}

export function PackModel({ format, front, back, side: sideUrl, colour }: PackModelProps) {
  const [f, b, s] = useLabel(front, back, sideUrl);
  const side = useMemo(() => new THREE.Color(colour), [colour]);
  const dark = useMemo(() => side.clone().multiplyScalar(0.8), [side]);

  const mats = useMemo(() => {
    const rough = format === "pouch" ? 0.38 : format === "sack" ? 0.85 : 0.6;
    const m = (o: THREE.MeshStandardMaterialParameters) => new THREE.MeshStandardMaterial({ roughness: rough, metalness: 0, ...o });
    // BoxGeometry order: +x, -x, +y, -y, +z (front), -z (back)
    return [m({ map: s }), m({ map: s }), m({ color: dark }), m({ color: dark }), m({ map: f }), m({ map: b })];
  }, [f, b, s, dark, format]);

  const geo = useMemo(() => {
    switch (format) {
      case "sack":
        return pillowGeometry(0.42, (ny) => Math.sqrt(Math.max(0, 1 - Math.abs(ny) ** 10)));
      case "pouch":
        // gusseted bottom, heat-sealed top
        return pillowGeometry(0.36, (ny) => (ny > 0.9 ? 0.06 : 0.2 + 0.8 * (1 - ((ny + 1) / 1.9) ** 2.2)), 8);
      case "sleeve":
        return new THREE.BoxGeometry(LW, LH, 0.14);
      default:
        return new THREE.BoxGeometry(LW, LH, 0.62);
    }
  }, [format]);

  if (format === "tub") return <Tub front={f} colour={colour} />;
  if (format === "bottle") return <Jerrycan front={f} colour={colour} />;
  return <mesh geometry={geo} material={mats} castShadow />;
}

/** Tapered tub with a wrap-around label patch and a coloured lid. */
function Tub({ front, colour }: { front: THREE.Texture; colour: string }) {
  const h = 1.15, rTop = 0.66, rBot = 0.56;
  const labelH = 0.86, labelW = (labelH * LW) / LH, labelY = -0.02;
  // radius of the tapered wall at height y, plus a hair so the label sits on top
  const r = (y: number) => rBot + ((rTop - rBot) * (y + h / 2)) / h + 0.005;
  const theta = labelW / r(labelY);
  return (
    <group>
      <mesh castShadow>
        <cylinderGeometry args={[rTop, rBot, h, 64]} />
        <meshStandardMaterial color="#F7F5EF" roughness={0.35} />
      </mesh>
      <mesh position={[0, labelY, 0]}>
        <cylinderGeometry args={[r(labelY + labelH / 2), r(labelY - labelH / 2), labelH, 48, 1, true, -theta / 2, theta]} />
        <meshStandardMaterial map={front} roughness={0.5} />
      </mesh>
      <mesh position={[0, h / 2 + 0.05, 0]} castShadow>
        <cylinderGeometry args={[rTop + 0.04, rTop + 0.04, 0.1, 64]} />
        <meshStandardMaterial color={colour} roughness={0.4} />
      </mesh>
    </group>
  );
}

/** Jerrycan for liquid flavours: block body, handle, cap, front label. */
function Jerrycan({ front, colour }: { front: THREE.Texture; colour: string }) {
  const w = 1.0, h = 1.45, d = 0.62;
  return (
    <group>
      <mesh castShadow>
        <boxGeometry args={[w, h, d]} />
        <meshStandardMaterial color="#F1E9D2" roughness={0.3} transparent opacity={0.96} />
      </mesh>
      <mesh position={[0, -0.04, d / 2 + 0.002]}>
        <planeGeometry args={[0.78, 0.78 * (LH / LW)]} />
        <meshStandardMaterial map={front} roughness={0.55} />
      </mesh>
      <mesh position={[-0.18, h / 2 + 0.16, 0]} rotation={[0, 0, 0]}>
        <torusGeometry args={[0.2, 0.05, 12, 32, Math.PI]} />
        <meshStandardMaterial color="#F1E9D2" roughness={0.3} />
      </mesh>
      <mesh position={[0.3, h / 2 + 0.08, 0]} castShadow>
        <cylinderGeometry args={[0.12, 0.12, 0.16, 32]} />
        <meshStandardMaterial color={colour} roughness={0.4} />
      </mesh>
    </group>
  );
}
